import { useEffect, useState } from "react";

import {
  LayoutDashboard,
  Users,
  ShieldCheck,
  Settings,
  BarChart3,
  ClipboardList,
  LogOut,
  Menu,
  X,
} from "lucide-react";

/*
  Add to index.html:
  <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700;800&family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet">

  Usage (the sidebar is fixed on desktop, so give your page content left padding):

  <Sidebar activeItem="dashboard" onNavigate={(item) => navigate(item.path)} onLogout={handleLogout} />
  <div className="lg:pl-64"> ...your page... </div>

  With React Router, replace the <a> inside NavItem with <NavLink to={item.path}>.
*/

// College crest embedded as base64
const logo =
  "data:image/png;base64,";

const MENU = [
  { id: "dashboard", label: "Dashboard", icon: LayoutDashboard, path: "/dashboard" },
  { id: "users", label: "Manage Users", icon: Users, path: "/users" },
  { id: "admins", label: "Manage Admin Panels", icon: ShieldCheck, path: "/admin-panels" },
  { id: "settings", label: "System Settings", icon: Settings, path: "/settings" },
  { id: "reports", label: "Reports & Analytics", icon: BarChart3, path: "/reports" },
  { id: "audit", label: "Audit Logs", icon: ClipboardList, path: "/audit-logs" },
];

export default function Sidebar({ activeItem = "dashboard", onNavigate, onLogout }) {
  const [active, setActive] = useState(activeItem);
  const [open, setOpen] = useState(false); // mobile drawer

  useEffect(() => setActive(activeItem), [activeItem]);

  // Close the mobile drawer with Escape
  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && setOpen(false);
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const handleClick = (e, item) => {
    if (onNavigate) {
      e.preventDefault();
      onNavigate(item);
    }
    setActive(item.id);
    setOpen(false);
  };

  return (
    <>
      {/* Mobile menu button */}
      <button
        onClick={() => setOpen(true)}
        aria-label="Open menu"
        className="fixed left-4 top-4 z-30 grid h-11 w-11 place-items-center rounded-lg bg-[#14234b] text-white shadow-lg lg:hidden"
      >
        <Menu size={22} />
      </button>

      {/* Mobile overlay */}
      {open && (
        <div
          className="fixed inset-0 z-40 bg-black/50 backdrop-blur-[2px] lg:hidden"
          onClick={() => setOpen(false)}
          aria-hidden="true"
        />
      )}

      <aside
        aria-label="Sidebar"
        className={`fixed inset-y-0 left-0 z-50 flex w-64 flex-col bg-gradient-to-b from-[#14234b] via-[#14234b] to-[#0d1733] font-['Poppins',sans-serif] text-white shadow-2xl transition-transform duration-300 lg:translate-x-0 ${
          open ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        {/* Close button (mobile) */}
        <button
          onClick={() => setOpen(false)}
          aria-label="Close menu"
          className="absolute right-3 top-3 rounded-md p-1.5 text-white/70 hover:bg-white/10 hover:text-white lg:hidden"
        >
          <X size={20} />
        </button>

        {/* Brand */}
        <div className="relative px-5 pb-6 pt-8 text-center">
          <span className="mx-auto grid h-20 w-20 place-items-center rounded-full bg-white p-1.5 shadow-lg ring-4 ring-[#f2c200]/60">
            <img
              src={logo}
              alt="M.C.E. Society’s Abeda Inamdar Senior College crest"
              className="h-full w-full object-contain"
            />
          </span>
          <h1 className="mt-4 font-['Playfair_Display',serif] text-xl font-bold leading-tight">
            Abeda Inamdar
            <span className="block text-[#f2c200]">Senior College</span>
          </h1>
          <div className="mx-auto mt-4 h-px w-full bg-gradient-to-r from-transparent via-white/25 to-transparent" />
        </div>

        {/* Navigation */}
        <nav className="flex-1 overflow-y-auto px-3 pb-4" aria-label="Main navigation">
          <ul className="space-y-1.5">
            {MENU.map((item) => {
              const Icon = item.icon;
              const isActive = active === item.id;
              return (
                <li key={item.id}>
                  <a
                    href={item.path}
                    onClick={(e) => handleClick(e, item)}
                    aria-current={isActive ? "page" : undefined}
                    className={`group relative flex items-center gap-3 rounded-xl px-4 py-3 text-sm font-medium transition focus-visible:outline focus-visible:outline-2 focus-visible:outline-[#f2c200] ${
                      isActive
                        ? "bg-white text-[#8f0014] shadow-lg"
                        : "text-white/85 hover:bg-white/10 hover:text-white"
                    }`}
                  >
                    {isActive && (
                      <span className="absolute -left-3 top-1/2 h-7 w-1.5 -translate-y-1/2 rounded-r-full bg-[#f2c200]" aria-hidden="true" />
                    )}
                    <Icon size={19} className={isActive ? "" : "transition group-hover:scale-110"} />
                    <span className="truncate">{item.label}</span>
                  </a>
                </li>
              );
            })}
          </ul>
        </nav>

        {/* Logout */}
        <div className="border-t border-white/10 p-3">
          <button
            onClick={onLogout}
            className="group flex w-full items-center gap-3 rounded-xl px-4 py-3 text-sm font-medium text-white/85 transition hover:bg-[#8f0014] hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-[#f2c200]"
          >
            <LogOut size={19} className="transition group-hover:-translate-x-0.5" />
            Logout
          </button>
        </div>
      </aside>
    </>
  );
}